import { describe, expect, test } from "vite-plus/test";
import { AGENT_CLIENTS, appSetup, cliSetup } from "./agentSetup";

const URL = "http://127.0.0.1:64343/mcp";
const TOKEN = "<REDACTED>";

describe("cliSetup", () => {
  test("uses each client's own add command", () => {
    expect(cliSetup("claude_code").snippet).toBe("claude mcp add yaak -- yaak mcp");
    expect(cliSetup("codex").snippet).toBe("codex mcp add yaak -- yaak mcp");
  });

  test("writes the config shape each client reads", () => {
    expect(JSON.parse(cliSetup("cursor").snippet)).toEqual({
      mcpServers: { yaak: { command: "yaak", args: ["mcp"] } },
    });
    expect(JSON.parse(cliSetup("vscode").snippet)).toEqual({
      servers: { yaak: { type: "stdio", command: "yaak", args: ["mcp"] } },
    });
    expect(JSON.parse(cliSetup("other").snippet)).toEqual({
      mcpServers: { yaak: { command: "yaak", args: ["mcp"] } },
    });
  });
});

describe("appSetup", () => {
  test("passes the token as a bearer header", () => {
    expect(appSetup("claude_code", URL, TOKEN).snippet).toBe(
      `claude mcp add --transport http yaak ${URL} --header "Authorization: Bearer ${TOKEN}"`,
    );
    expect(appSetup("codex", URL, TOKEN).snippet).toBe(
      `[mcp_servers.yaak]\nurl = "${URL}"\nhttp_headers = { "Authorization" = "Bearer ${TOKEN}" }`,
    );
    expect(JSON.parse(appSetup("cursor", URL, TOKEN).snippet)).toEqual({
      mcpServers: { yaak: { url: URL, headers: { Authorization: `Bearer ${TOKEN}` } } },
    });
    expect(JSON.parse(appSetup("vscode", URL, TOKEN).snippet)).toEqual({
      servers: { yaak: { type: "http", url: URL, headers: { Authorization: `Bearer ${TOKEN}` } } },
    });
    expect(JSON.parse(appSetup("other", URL, TOKEN).snippet)).toEqual({
      mcpServers: {
        yaak: {
          command: "npx",
          args: ["-y", "mcp-remote", URL, "--header", `Authorization: Bearer ${TOKEN}`],
        },
      },
    });
  });

  test("keeps argument lists on one line", () => {
    expect(appSetup("other", URL, TOKEN).snippet).toContain(
      `"args": ["-y", "mcp-remote", "${URL}", "--header", "Authorization: Bearer ${TOKEN}"]`,
    );
  });

  test("covers every listed client", () => {
    for (const { value } of AGENT_CLIENTS) {
      expect(cliSetup(value).snippet).not.toBe("");
      expect(appSetup(value, URL, TOKEN).snippet).toContain(TOKEN);
    }
  });
});

import { describe, expect, test } from "vite-plus/test";
import type { JsonSchema } from "./jsonSchemaExample";
import { buildExampleFromSchema } from "./jsonSchemaExample";

describe("buildExampleFromSchema", () => {
  test("fills scalar fields with placeholders", () => {
    const schema: JsonSchema = {
      type: "object",
      properties: {
        name: { type: "string" },
        age: { type: "number", format: "int32" },
        active: { type: "boolean" },
        data: { type: "string", format: "byte" },
      },
    };

    expect(buildExampleFromSchema(schema)).toEqual({
      name: "",
      age: 0,
      active: false,
      data: "",
    });
  });

  test("encodes 64-bit integers as strings", () => {
    const schema: JsonSchema = {
      type: "object",
      properties: {
        id: { type: "string", format: "int64" },
        count: { type: "string", format: "uint64" },
        offset: { type: "string", format: "sfixed64" },
      },
    };

    expect(buildExampleFromSchema(schema)).toEqual({ id: "0", count: "0", offset: "0" });
  });

  test("fills date-time with a parseable timestamp", () => {
    const schema: JsonSchema = {
      type: "object",
      properties: { createdAt: { type: "string", format: "date-time" } },
    };

    const example = buildExampleFromSchema(schema) as { createdAt: string };
    expect(Number.isNaN(Date.parse(example.createdAt))).toBe(false);
  });

  test("fills a duration with a value that parses", () => {
    const schema: JsonSchema = {
      type: "object",
      properties: { timeout: { type: "string", format: "duration" } },
    };

    // An empty string fails protobuf's Duration parsing, so the message wouldn't send
    expect(buildExampleFromSchema(schema)).toEqual({ timeout: "0s" });
  });

  test("expands nested messages through $defs", () => {
    const schema: JsonSchema = {
      type: "object",
      properties: { user: { $ref: "#/$defs/example.User" } },
      $defs: {
        "example.User": {
          type: "object",
          properties: {
            name: { type: "string" },
            address: { $ref: "#/$defs/example.Address" },
          },
        },
        "example.Address": {
          type: "object",
          properties: { city: { type: "string" } },
        },
      },
    };

    expect(buildExampleFromSchema(schema)).toEqual({
      user: { name: "", address: { city: "" } },
    });
  });

  test("gives repeated fields a single placeholder item", () => {
    const schema: JsonSchema = {
      type: "object",
      properties: {
        tags: { type: "array", items: { type: "string" } },
        users: { type: "array", items: { $ref: "#/$defs/example.User" } },
        unknown: { type: "array" },
      },
      $defs: {
        "example.User": { type: "object", properties: { name: { type: "string" } } },
      },
    };

    expect(buildExampleFromSchema(schema)).toEqual({
      tags: [""],
      users: [{ name: "" }],
      unknown: [],
    });
  });

  test("uses the first value of an enum", () => {
    const schema: JsonSchema = {
      type: "object",
      properties: {
        status: { type: "string", enum: ["STATUS_UNSPECIFIED", "STATUS_ACTIVE"] },
        empty: { type: "string", enum: [] },
      },
    };

    expect(buildExampleFromSchema(schema)).toEqual({ status: "STATUS_UNSPECIFIED", empty: "" });
  });

  test("gives maps a single placeholder entry", () => {
    const schema: JsonSchema = {
      type: "object",
      properties: {
        labels: { type: "object", additionalProperties: { type: "string" } },
        users: { type: "object", additionalProperties: { $ref: "#/$defs/example.User" } },
      },
      $defs: {
        "example.User": { type: "object", properties: { name: { type: "string" } } },
      },
    };

    expect(buildExampleFromSchema(schema)).toEqual({
      labels: { key: "" },
      users: { key: { name: "" } },
    });
  });

  test("stops at the root self-reference", () => {
    const schema: JsonSchema = {
      type: "object",
      properties: {
        value: { type: "string" },
        children: { type: "array", items: { $ref: "#" } },
      },
    };

    expect(buildExampleFromSchema(schema)).toEqual({ value: "", children: [{}] });
  });

  test("stops at a cycle between messages", () => {
    const schema: JsonSchema = {
      type: "object",
      properties: { node: { $ref: "#/$defs/example.Node" } },
      $defs: {
        "example.Node": {
          type: "object",
          properties: {
            name: { type: "string" },
            parent: { $ref: "#/$defs/example.Node" },
            leaf: { $ref: "#/$defs/example.Leaf" },
          },
        },
        "example.Leaf": {
          type: "object",
          properties: { node: { $ref: "#/$defs/example.Node" } },
        },
      },
    };

    expect(buildExampleFromSchema(schema)).toEqual({
      node: { name: "", parent: {}, leaf: { node: {} } },
    });
  });

  test("expands the same message twice when it is not on the same path", () => {
    const schema: JsonSchema = {
      type: "object",
      properties: {
        from: { $ref: "#/$defs/example.User" },
        to: { $ref: "#/$defs/example.User" },
      },
      $defs: {
        "example.User": { type: "object", properties: { name: { type: "string" } } },
      },
    };

    expect(buildExampleFromSchema(schema)).toEqual({ from: { name: "" }, to: { name: "" } });
  });

  test("fills every branch of a flattened oneof", () => {
    const schema: JsonSchema = {
      type: "object",
      properties: {
        id: { type: "string" },
        text: { type: "string" },
        image: { $ref: "#/$defs/example.Image" },
      },
      $defs: {
        "example.Image": { type: "object", properties: { url: { type: "string" } } },
      },
    };

    expect(buildExampleFromSchema(schema)).toEqual({
      id: "",
      text: "",
      image: { url: "" },
    });
  });

  test("stops expanding once the node budget runs out", () => {
    // Every level references the next one twice, so an unbounded walk would build 2^depth
    // nodes without ever repeating a ref on the same path.
    const depth = 16;
    const $defs: Record<string, JsonSchema> = { [`d${depth}`]: { type: "string" } };
    for (let i = 0; i < depth; i++) {
      $defs[`d${i}`] = {
        type: "object",
        properties: {
          a: { $ref: `#/$defs/d${i + 1}` },
          b: { $ref: `#/$defs/d${i + 1}` },
        },
      };
    }

    const example = buildExampleFromSchema({
      type: "object",
      properties: { root: { $ref: "#/$defs/d0" } },
      $defs,
    });

    // 2 ** 16 nodes unbounded; the budget holds it to a couple of thousand
    expect(countNodes(example)).toBeLessThan(10_000);
  });

  test("handles messages without a known type", () => {
    const schema: JsonSchema = {
      type: "object",
      properties: {
        empty: {},
        struct: { type: "object" },
        missing: { $ref: "#/$defs/example.Nope" },
      },
    };

    expect(buildExampleFromSchema(schema)).toEqual({ empty: null, struct: {}, missing: {} });
  });
});

function countNodes(value: unknown): number {
  if (Array.isArray(value)) {
    return 1 + value.reduce((total: number, v) => total + countNodes(v), 0);
  }
  if (value !== null && typeof value === "object") {
    return 1 + Object.values(value).reduce((total: number, v) => total + countNodes(v), 0);
  }
  return 1;
}

use axum::Router;
use axum::body::{Body, to_bytes};
use axum::extract::ConnectInfo;
use axum::http::{HeaderMap, Request, StatusCode, header};
use serde_json::{Value, json};
use std::collections::BTreeSet;
use std::net::SocketAddr;
use tower::ServiceExt;
use yaak_playground::{Config, router};

const ALICE: [u8; 4] = [203, 0, 113, 1];
const BOB: [u8; 4] = [203, 0, 113, 2];

fn config() -> Config {
    Config {
        host: "127.0.0.1".to_string(),
        port: 0,
        rate_limit_per_minute: 1000,
        trust_forwarded_for: false,
        reset_after_secs: 3600,
        max_clients: 10,
        max_posts_per_client: 20,
        max_request_bytes: 4096,
    }
}

struct Res {
    status: StatusCode,
    headers: HeaderMap,
    json: Value,
}

async fn call(
    app: &Router,
    client: [u8; 4],
    method: &str,
    uri: &str,
    headers: &[(&str, &str)],
    body: Option<Value>,
) -> Res {
    let mut req = Request::builder().method(method).uri(uri);
    for (name, value) in headers {
        req = req.header(*name, *value);
    }
    let body = match body {
        Some(v) => Body::from(v.to_string()),
        None => Body::empty(),
    };
    let mut req = req.body(body).unwrap();
    req.extensions_mut().insert(ConnectInfo(SocketAddr::from((client, 40000))));
    let res = app.clone().oneshot(req).await.unwrap();
    let status = res.status();
    let headers = res.headers().clone();
    let bytes = to_bytes(res.into_body(), 1024 * 1024).await.unwrap();
    let json = if bytes.is_empty() { Value::Null } else { serde_json::from_slice(&bytes).unwrap() };
    Res { status, headers, json }
}

#[tokio::test]
async fn users_and_todos() {
    let app = router(config());
    let res = call(&app, ALICE, "GET", "/users", &[], None).await;
    assert_eq!(res.status, StatusCode::OK);
    assert_eq!(res.json[0]["username"], "ada");

    let res = call(&app, ALICE, "GET", "/users/2", &[], None).await;
    assert_eq!(res.json["name"], "Grace Hopper");

    for uri in ["/users/99", "/users/abc", "/users/99/todos"] {
        let res = call(&app, ALICE, "GET", uri, &[], None).await;
        assert_eq!(res.status, StatusCode::NOT_FOUND, "{uri}");
        assert!(res.json["error"].is_string());
    }

    let res = call(&app, ALICE, "GET", "/users/1/todos?completed=false&limit=1", &[], None).await;
    assert_eq!(res.json.as_array().unwrap().len(), 1);
    assert_eq!(res.json[0]["userId"], 1);
    assert_eq!(res.json[0]["completed"], false);

    let res = call(&app, ALICE, "GET", "/todos?userId=3", &[], None).await;
    assert!(res.json.as_array().unwrap().iter().all(|t| t["userId"] == 3));

    let res = call(&app, ALICE, "GET", "/todos?completed=maybe", &[], None).await;
    assert_eq!(res.status, StatusCode::BAD_REQUEST);
}

#[tokio::test]
async fn writes_are_private_to_the_client() {
    let app = router(config());
    let new_post = json!({ "userId": 1, "title": "Hello", "body": "From Yaak" });
    let res = call(&app, ALICE, "POST", "/posts", &[], Some(new_post)).await;
    assert_eq!(res.status, StatusCode::CREATED);
    let id = res.json["id"].as_u64().unwrap();
    assert_eq!(res.headers[header::LOCATION], format!("/posts/{id}"));

    let uri = format!("/posts/{id}");
    assert_eq!(call(&app, ALICE, "GET", &uri, &[], None).await.status, StatusCode::OK);
    assert_eq!(call(&app, BOB, "GET", &uri, &[], None).await.status, StatusCode::NOT_FOUND);

    let res = call(&app, ALICE, "PATCH", &uri, &[], Some(json!({ "title": "Edited" }))).await;
    assert_eq!(res.json["title"], "Edited");
    assert_eq!(res.json["body"], "From Yaak");

    let replacement = json!({ "userId": 2, "title": "Replaced", "body": "" });
    let res = call(&app, ALICE, "PUT", &uri, &[], Some(replacement)).await;
    assert_eq!(res.json["userId"], 2);

    let res = call(&app, ALICE, "DELETE", "/posts/1", &[], None).await;
    assert_eq!(res.status, StatusCode::NO_CONTENT);
    assert_eq!(call(&app, ALICE, "GET", "/posts/1", &[], None).await.status, StatusCode::NOT_FOUND);
    assert_eq!(call(&app, BOB, "GET", "/posts/1", &[], None).await.status, StatusCode::OK);

    let res = call(&app, ALICE, "GET", "/posts?userId=2", &[], None).await;
    assert!(res.json.as_array().unwrap().iter().any(|p| p["title"] == "Replaced"));
}

#[tokio::test]
async fn invalid_posts_are_rejected() {
    let app = router(config());
    let cases = [
        json!({ "title": "No user", "body": "" }),
        json!({ "userId": 99, "title": "Unknown user", "body": "" }),
        json!({ "userId": 1, "title": "  ", "body": "" }),
        json!({ "userId": 1, "title": "x".repeat(201), "body": "" }),
    ];
    for body in cases {
        let res = call(&app, ALICE, "POST", "/posts", &[], Some(body.clone())).await;
        assert_eq!(res.status, StatusCode::BAD_REQUEST, "{body}");
        assert!(res.json["error"].is_string());
    }

    let res = call(&app, ALICE, "POST", "/posts", &[], None).await;
    assert_eq!(res.status, StatusCode::BAD_REQUEST);

    let huge = json!({ "userId": 1, "title": "Big", "body": "x".repeat(5000) });
    let res = call(&app, ALICE, "POST", "/posts", &[], Some(huge)).await;
    assert_eq!(res.status, StatusCode::PAYLOAD_TOO_LARGE);
    assert!(res.json["error"].is_string());
}

#[tokio::test]
async fn post_cap_and_reset() {
    let app = router(Config { max_posts_per_client: 11, ..config() });
    let post = json!({ "userId": 1, "title": "One more", "body": "" });
    assert_eq!(
        call(&app, ALICE, "POST", "/posts", &[], Some(post.clone())).await.status,
        StatusCode::CREATED
    );
    assert_eq!(
        call(&app, ALICE, "POST", "/posts", &[], Some(post)).await.status,
        StatusCode::CONFLICT
    );

    let app = router(Config { reset_after_secs: 0, ..config() });
    call(&app, ALICE, "DELETE", "/posts/1", &[], None).await;
    assert_eq!(call(&app, ALICE, "GET", "/posts/1", &[], None).await.status, StatusCode::OK);
}

#[tokio::test]
async fn bearer_token_flow() {
    let app = router(config());
    let res = call(&app, ALICE, "GET", "/auth/me", &[], None).await;
    assert_eq!(res.status, StatusCode::UNAUTHORIZED);
    assert_eq!(res.headers[header::WWW_AUTHENTICATE], "Bearer");

    let bad = json!({ "username": "ada", "password": "nope" });
    assert_eq!(
        call(&app, ALICE, "POST", "/auth/token", &[], Some(bad)).await.status,
        StatusCode::UNAUTHORIZED
    );

    let good = json!({ "username": "grace", "password": "yaak" });
    let res = call(&app, ALICE, "POST", "/auth/token", &[], Some(good)).await;
    assert_eq!(res.status, StatusCode::OK);
    let token = <REDACTED>"accessToken"].as_str().unwrap().to_string();

    let auth = format!("Bearer {token}");
    let res = call(&app, BOB, "GET", "/auth/me", &[("authorization", &auth)], None).await;
    assert_eq!(res.json["username"], "grace");

    let res =
        call(&app, ALICE, "GET", "/auth/me", &[("authorization", "Bearer wrong")], None).await;
    assert_eq!(res.status, StatusCode::UNAUTHORIZED);

    let cookie = format!("session={token}");
    let res = call(&app, ALICE, "GET", "/auth/session", &[("cookie", &cookie)], None).await;
    assert_eq!(res.status, StatusCode::UNAUTHORIZED);
}

#[tokio::test]
async fn session_cookie_flow() {
    let app = router(config());
    let login = json!({ "username": "alan", "password": "yaak" });
    let res =
        call(&app, ALICE, "POST", "/auth/session", &[("x-forwarded-proto", "https")], Some(login))
            .await;
    assert_eq!(res.status, StatusCode::OK);
    let set_cookie = res.headers[header::SET_COOKIE].to_str().unwrap();
    assert!(set_cookie.contains("HttpOnly") && set_cookie.contains("; Secure"), "{set_cookie}");
    let cookie = set_cookie.split(';').next().unwrap().to_string();

    let headers = [("cookie", cookie.as_str())];
    let res = call(&app, ALICE, "GET", "/auth/session", &headers, None).await;
    assert_eq!(res.json["username"], "alan");

    let id = cookie.trim_start_matches("session=");
    let auth = format!("Bearer {id}");
    let res = call(&app, ALICE, "GET", "/auth/me", &[("authorization", &auth)], None).await;
    assert_eq!(res.status, StatusCode::UNAUTHORIZED);

    let res = call(&app, ALICE, "DELETE", "/auth/session", &headers, None).await;
    assert_eq!(res.status, StatusCode::NO_CONTENT);
    assert!(res.headers[header::SET_COOKIE].to_str().unwrap().contains("Max-Age=0"));
    assert_eq!(
        call(&app, ALICE, "GET", "/auth/session", &headers, None).await.status,
        StatusCode::UNAUTHORIZED
    );
}

#[tokio::test]
async fn rate_limit() {
    let app = router(Config { rate_limit_per_minute: 2, ..config() });
    call(&app, ALICE, "GET", "/users", &[], None).await;
    call(&app, ALICE, "GET", "/users", &[], None).await;
    let res = call(&app, ALICE, "GET", "/users", &[], None).await;
    assert_eq!(res.status, StatusCode::TOO_MANY_REQUESTS);
    assert!(res.headers.contains_key(header::RETRY_AFTER));
    assert_eq!(call(&app, BOB, "GET", "/users", &[], None).await.status, StatusCode::OK);
}

#[tokio::test]
async fn openapi_matches_the_routes() {
    let app = router(config());
    let spec = call(&app, ALICE, "GET", "/openapi.json", &[], None).await.json;
    let mut documented = BTreeSet::new();
    for (path, item) in spec["paths"].as_object().unwrap() {
        for (method, _) in item.as_object().unwrap() {
            let method = method.to_uppercase();
            let uri = path.replace("{id}", "1");
            // A fresh client per call, so a DELETE can't hide the GET that follows it
            let client = [198, 51, 100, documented.len() as u8];
            let res = call(&app, client, &method, &uri, &[], None).await;
            assert!(
                res.status != StatusCode::NOT_FOUND && res.status != StatusCode::METHOD_NOT_ALLOWED,
                "{method} {path} is documented but not routed ({})",
                res.status
            );
            documented.insert(format!("{method} {path}"));
        }
    }

    let index = call(&app, ALICE, "GET", "/", &[], None).await.json;
    let listed: BTreeSet<String> = index["endpoints"]
        .as_array()
        .unwrap()
        .iter()
        .map(|e| e.as_str().unwrap().to_string())
        .collect();
    assert_eq!(listed, documented);

    assert_eq!(call(&app, ALICE, "GET", "/nope", &[], None).await.status, StatusCode::NOT_FOUND);
}

-- Add a setting to run the built-in MCP server
ALTER TABLE settings
    ADD COLUMN mcp_server_enabled BOOLEAN DEFAULT FALSE NOT NULL;

import type { Context, PluginDefinition } from "@yaakapp/api";
import { createMcpServer } from "./server.js";

const serverPort = parseInt(process.env.YAAK_PLUGIN_MCP_SERVER_PORT ?? "64343", 10);

let mcpServer: Awaited<ReturnType<typeof createMcpServer>> | null = null;

export const plugin: PluginDefinition = {
  async init(ctx: Context) {
    // Start the server after waiting, so there's an active window open to do things
    // like show the startup toast.
    console.log("Initializing MCP Server plugin");
    setTimeout(async () => {
      void ctx.toast.show({
        message:
          "The MCP Server plugin is deprecated. Yaak now has a built-in MCP server: uninstall this plugin, then turn it on in Settings > Agents.",
        icon: "alert_triangle",
        color: "notice",
        timeout: 30000,
      });
      try {
        mcpServer = createMcpServer({ yaak: ctx }, serverPort);
      } catch (err) {
        console.error("Failed to start MCP server:", err);
        void ctx.toast.show({
          message: `Failed to start MCP Server: ${err instanceof Error ? err.message : String(err)}`,
          icon: "alert_triangle",
          color: "danger",
          timeout: 10000,
        });
      }
    }, 5000);
  },

  async dispose() {
    console.log("Disposing MCP Server plugin");

    if (mcpServer) {
      await mcpServer.close();
      mcpServer = null;
    }
  },
};

import type { PluginDefinition } from "@yaakapp/api";

export const plugin: PluginDefinition = {
  authentication: {
    name: "apikey",
    label: "API Key",
    shortLabel: "API Key",
    args: [
      {
        type: "select",
        name: "location",
        label: "Behavior",
        defaultValue: "header",
        options: [
          { label: "Insert Header", value: "header" },
          { label: "Append Query Parameter", value: "query" },
        ],
      },
      {
        type: "text",
        name: "key",
        label: "Key",
        dynamic: (_ctx, { values }) => {
          return values.location === "query"
            ? {
                label: "Parameter Name",
                description: "The name of the query parameter to add to the request",
              }
            : {
                label: "Header Name",
                description: "The name of the header to add to the request",
              };
        },
      },
      {
        type: "text",
        name: "value",
        label: "API Key",
        optional: true,
        password: <REDACTED>
      },
    ],
    async onApply(_ctx, { values }) {
      const key = String(values.key ?? "");
      const value = String(values.value ?? "");
      const location = String(values.location);

      if (location === "query") {
        return { setQueryParameters: [{ name: key, value }] };
      }
      return { setHeaders: [{ name: key, value }] };
    },
  },
};

