use crate::AppState;
use crate::data::{self, User};
use crate::error::{ApiError, ApiResult, parse_json};
use axum::extract::State;
use axum::extract::rejection::BytesRejection;
use axum::http::{HeaderMap, HeaderValue, StatusCode, header};
use axum::response::{IntoResponse, Json, Response};
use bytes::Bytes;
use serde::Deserialize;
use serde_json::{Value, json};
use std::collections::HashMap;
use std::sync::Mutex;
use std::time::{Duration, Instant};

pub const PASSWORD: <REDACTED> = "yaak";
const SESSION_COOKIE: &str = "session";
const TTL: Duration = Duration::from_secs(60 * 60);
const MAX_CREDENTIALS: usize = 10_000;

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Kind {
    Bearer,
    Session,
}

/// Issued tokens and session IDs, kept apart so a token can't be sent as a cookie or the
/// other way around.
pub struct Credentials {
    entries: Mutex<HashMap<String, Entry>>,
}

struct Entry {
    user_id: u64,
    kind: Kind,
    expires: Instant,
}

impl Credentials {
    pub fn new() -> Self {
        Self { entries: Mutex::new(HashMap::new()) }
    }

    fn issue(&self, user_id: u64, kind: Kind) -> String {
        let value = uuid::Uuid::new_v4().simple().to_string();
        let now = Instant::now();
        let mut entries = self.entries.lock().unwrap_or_else(|e| e.into_inner());
        if entries.len() >= MAX_CREDENTIALS {
            entries.retain(|_, e| e.expires > now);
        }
        if entries.len() >= MAX_CREDENTIALS
            && let Some(oldest) =
                entries.iter().min_by_key(|(_, e)| e.expires).map(|(k, _)| k.clone())
        {
            entries.remove(&oldest);
        }
        entries.insert(value.clone(), Entry { user_id, kind, expires: now + TTL });
        value
    }

    fn lookup(&self, value: &str, kind: Kind) -> Option<&'static User> {
        let entries = self.entries.lock().unwrap_or_else(|e| e.into_inner());
        let entry = entries.get(value)?;
        if entry.kind != kind || entry.expires <= Instant::now() {
            return None;
        }
        data::user(entry.user_id)
    }

    fn revoke(&self, value: &str) {
        self.entries.lock().unwrap_or_else(|e| e.into_inner()).remove(value);
    }
}

#[derive(Deserialize)]
struct Login {
    username: String,
    password: <REDACTED>
}

fn log_in(body: Result<Bytes, BytesRejection>) -> ApiResult<&'static User> {
    let login: Login = parse_json(body)?;
    data::user_by_username(&login.username)
        .filter(|_| login.password =<REDACTED> PASSWORD)
        .ok_or_else(|| ApiError::unauthorized("Invalid username or password", None))
}

pub async fn create_token(
    State(state): State<AppState>,
    body: Result<Bytes, BytesRejection>,
) -> ApiResult<Json<Value>> {
    let user = log_in(body)?;
    let token = <REDACTED> Kind::Bearer);
    Ok(Json(json!({
        "accessToken": token,
        "tokenType": "Bearer",
        "expiresIn": TTL.as_secs(),
    })))
}

pub async fn me(
    State(state): State<AppState>,
    headers: HeaderMap,
) -> ApiResult<Json<&'static User>> {
    let Some(authorization) = headers.get(header::AUTHORIZATION).and_then(|v| v.to_str().ok())
    else {
        return Err(ApiError::unauthorized("Missing Authorization header", Some("Bearer")));
    };
    let token = <REDACTED> authorization.split_once(' ') {
        Some((scheme, token)) if scheme.eq_ignore_ascii_case("bearer") => token.trim(),
        _ => {
            return Err(ApiError::unauthorized(
                "Authorization header must be \"Bearer <token>\"",
                Some("Bearer"),
            ));
        }
    };
    state.credentials.lookup(token, Kind::Bearer).map(Json).ok_or_else(|| {
        ApiError::unauthorized("Invalid or expired token", Some("Bearer error=\"invalid_token\""))
    })
}

pub async fn create_session(
    State(state): State<AppState>,
    headers: HeaderMap,
    body: Result<Bytes, BytesRejection>,
) -> ApiResult<Response> {
    let user = log_in(body)?;
    let id = state.credentials.issue(user.id, Kind::Session);
    let cookie = format!(
        "{SESSION_COOKIE}={id}; Path=/; Max-Age={}; HttpOnly; SameSite=Lax{}",
        TTL.as_secs(),
        secure_attribute(&headers)
    );
    let mut res = Json(user).into_response();
    res.headers_mut().insert(header::SET_COOKIE, HeaderValue::from_str(&cookie).expect("ascii"));
    Ok(res)
}

pub async fn session(
    State(state): State<AppState>,
    headers: HeaderMap,
) -> ApiResult<Json<&'static User>> {
    let Some(id) = session_cookie(&headers) else {
        return Err(ApiError::unauthorized("Missing session cookie", None));
    };
    state
        .credentials
        .lookup(id, Kind::Session)
        .map(Json)
        .ok_or_else(|| ApiError::unauthorized("Invalid or expired session", None))
}

pub async fn delete_session(State(state): State<AppState>, headers: HeaderMap) -> Response {
    if let Some(id) = session_cookie(&headers) {
        state.credentials.revoke(id);
    }
    let cookie = format!(
        "{SESSION_COOKIE}=; Path=/; Max-Age=0; HttpOnly; SameSite=Lax{}",
        secure_attribute(&headers)
    );
    let mut res = StatusCode::NO_CONTENT.into_response();
    res.headers_mut().insert(header::SET_COOKIE, HeaderValue::from_str(&cookie).expect("ascii"));
    res
}

fn session_cookie(headers: &HeaderMap) -> Option<&str> {
    headers
        .get_all(header::COOKIE)
        .iter()
        .filter_map(|v| v.to_str().ok())
        .flat_map(|v| v.split(';'))
        .filter_map(|pair| pair.trim().split_once('='))
        .find(|(name, _)| *name == SESSION_COOKIE)
        .map(|(_, value)| value)
}

/// `Secure` only when the request reached the proxy over HTTPS, so the cookie still works
/// against a local instance on plain HTTP.
fn secure_attribute(headers: &HeaderMap) -> &'static str {
    let https = headers
        .get("x-forwarded-proto")
        .and_then(|v| v.to_str().ok())
        .is_some_and(|v| v.eq_ignore_ascii_case("https"));
    if https { "; Secure" } else { "" }
}

use axum::Router;
use axum::body::{Body, to_bytes};
use axum::extract::{ConnectInfo, Request};
use axum::http::StatusCode;
use axum::routing::get;
use clap::Parser;
use std::io::{self, Write};
use std::net::SocketAddr;
use std::sync::{Arc, Mutex};
use tower::ServiceExt;
use yaak_web::{Config, DEFAULT_LOG_FILTER, router};

#[derive(Clone)]
struct LogCapture(Arc<Mutex<Vec<u8>>>);

impl Write for LogCapture {
    fn write(&mut self, bytes: &[u8]) -> io::Result<usize> {
        self.0.lock().unwrap().extend_from_slice(bytes);
        Ok(bytes.len())
    }

    fn flush(&mut self) -> io::Result<()> {
        Ok(())
    }
}

fn send_request(url: &str) -> Request {
    let payload = serde_json::json!({
        "request": { "url": url, "method": "GET" },
        "settings": {
            "validateCertificates": true,
            "followRedirects": true,
            "timeoutMs": 2000,
            "sendCookies": true,
            "storeCookies": true
        }
    });
    Request::builder()
        .method("POST")
        .uri("/v1/http/send")
        .header("content-type", "application/json")
        .extension(ConnectInfo("192.0.2.42:1234".parse::<SocketAddr>().unwrap()))
        .body(Body::from(payload.to_string()))
        .unwrap()
}

#[tokio::test]
async fn default_logging_keeps_operational_warnings_without_request_details() {
    let capture = LogCapture(Arc::new(Mutex::new(Vec::new())));
    env_logger::Builder::new()
        .parse_filters(DEFAULT_LOG_FILTER)
        .target(env_logger::Target::Pipe(Box::new(capture.clone())))
        .init();

    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let port = listener.local_addr().unwrap().port();
    let upstream = tokio::spawn(async move {
        axum::serve(
            listener,
            Router::new().route("/private-path", get(|| async { "secret body" })),
        )
        .await
        .unwrap();
    });
    let mut config = Config::parse_from(["yaak-web"]);
    config.allow_private_networks = true;
    config.rate_limit_per_minute = 1;
    let app = router(config.clone());
    assert!(String::from_utf8_lossy(&capture.0.lock().unwrap()).contains("ALLOWED"));
    capture.0.lock().unwrap().clear();

    // Exercise the HTTP engine and DNS lookup as well as the proxy's own logs.
    let url = format!("http://localhost:{port}/private-path?token=<REDACTED>");
    let response = app.clone().oneshot(send_request(&url)).await.unwrap();
    assert_eq!(response.status(), StatusCode::OK);
    let body = to_bytes(response.into_body(), 64 * 1024).await.unwrap();
    assert!(String::from_utf8_lossy(&body).contains("\"type\":\"done\""));
    assert_eq!(
        app.oneshot(send_request(&url)).await.unwrap().status(),
        StatusCode::TOO_MANY_REQUESTS
    );

    config.allow_private_networks = false;
    let app = router(config.clone());
    assert_eq!(
        app.oneshot(send_request("http://127.0.0.1/private-path")).await.unwrap().status(),
        StatusCode::FORBIDDEN
    );
    config.max_concurrent = 0;
    assert_eq!(
        router(config).oneshot(send_request(&url)).await.unwrap().status(),
        StatusCode::SERVICE_UNAVAILABLE
    );

    upstream.abort();
    let logs = capture.0.lock().unwrap();
    assert!(logs.is_empty(), "Unexpected request logs: {}", String::from_utf8_lossy(&logs));
}

use axum::body::{Body, to_bytes};
use axum::extract::Request;
use axum::http::{HeaderValue, StatusCode, header};
use axum::middleware::{self, Next};
use axum::response::Response;
use std::path::PathBuf;
use tower::ServiceExt;
use yaak_web::{Config, router};

fn config(serve: Option<PathBuf>) -> Config {
    Config {
        host: "127.0.0.1".to_string(),
        port: 0,
        app_port: None,
        serve,
        allow_private_networks: false,
        allowed_origins: vec!["*".into()],
        max_request_bytes: 1024,
        max_response_bytes: 2048,
        max_timeout_secs: 5,
        rate_limit_per_minute: 10,
        max_concurrent: 2,
        trust_forwarded_for: false,
    }
}

async fn mark_response(request: Request, next: Next) -> Response {
    let mut response = next.run(request).await;
    response.headers_mut().insert("x-hosted-middleware", HeaderValue::from_static("yes"));
    response
}

#[tokio::test]
async fn embedded_router_serves_api_without_static_files() {
    let app = router(config(None)).layer(middleware::from_fn(mark_response));
    let response = app
        .clone()
        .oneshot(Request::builder().uri("/v1/health").body(Body::empty()).unwrap())
        .await
        .unwrap();
    assert_eq!(response.status(), StatusCode::OK);
    assert_eq!(response.headers()["x-hosted-middleware"], "yes");
    let body = to_bytes(response.into_body(), 4096).await.unwrap();
    let health: serde_json::Value = serde_json::from_slice(&body).unwrap();
    assert_eq!(health["ok"], true);
    assert_eq!(health["maxResponseBytes"], 2048);
    assert_eq!(health["maxTimeoutSecs"], 5);

    let response = app.oneshot(Request::new(Body::empty())).await.unwrap();
    assert_eq!(response.status(), StatusCode::NOT_FOUND);
}

#[tokio::test]
async fn middleware_wraps_html_fallback_and_assets_alongside_api() {
    let dir = tempfile::tempdir().unwrap();
    std::fs::write(dir.path().join("index.html"), "<html>Yaak</html>").unwrap();
    std::fs::create_dir(dir.path().join("assets")).unwrap();
    std::fs::write(dir.path().join("assets/app-abc.js"), "// app").unwrap();
    let app = router(config(Some(dir.path().into()))).layer(middleware::from_fn(mark_response));

    for path in [
        "/",
        "/workspace/example",
        "/assets/app-abc.js",
        "/v1/health",
    ] {
        let response = app
            .clone()
            .oneshot(Request::builder().uri(path).body(Body::empty()).unwrap())
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK, "{path}");
        assert_eq!(response.headers()["x-hosted-middleware"], "yes", "{path}");
        if path.starts_with("/assets/") {
            assert_eq!(
                response.headers()[header::CACHE_CONTROL],
                "public, max-age=31536000, immutable"
            );
        } else if path == "/v1/health" {
            assert_eq!(response.headers()[header::CONTENT_TYPE], "application/json");
        } else {
            assert_eq!(response.headers()[header::CACHE_CONTROL], "no-cache");
            assert!(
                response.headers()[header::CONTENT_TYPE].to_str().unwrap().starts_with("text/html")
            );
            assert_eq!(to_bytes(response.into_body(), 4096).await.unwrap(), "<html>Yaak</html>");
        }
    }
}

