import { mkdtemp, mkdir, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import type { InternalEvent, InternalEventPayload } from "@yaakapp/api";
import { expect, test } from "vite-plus/test";
import { EventChannel } from "../src/EventChannel";
import { PluginInstance } from "../src/PluginInstance";

test("ctx.filter asks the host and hands back its reply", async () => {
  const dir = await mkdtemp(path.join(tmpdir(), "yaak-filter-"));
  await mkdir(path.join(dir, "build"));
  await writeFile(
    path.join(dir, "build/index.js"),
    `exports.plugin = { async init(ctx) {
      const results = [
        await ctx.filter.jsonPath('{"a":1}', "$.a"),
        await ctx.filter.xPath("<a/>", "//b["),
      ];
      await ctx.toast.show({ message: JSON.stringify(results) });
    } };`,
  );
  const channel = new EventChannel();
  const context = { workspaceId: null, label: null };
  const bootRequest = { dir, watch: false };
  const instance = new PluginInstance({ bootRequest, pluginRefId: "test", context }, channel);
  const requests: InternalEventPayload[] = [];
  const reply = (event: InternalEvent, payload: InternalEventPayload) =>
    instance.postMessage({ ...event, id: `reply-${event.id}`, replyId: event.id, payload });

  const toast = new Promise<string>((resolve, reject) => {
    channel.listen((event) => {
      const { payload } = event;
      if (payload.type === "filter_text_request") {
        // Match the JSON transport used by the real plugin host.
        requests.push(JSON.parse(JSON.stringify(payload)) as InternalEventPayload);
        reply(
          event,
          payload.language === "jsonpath"
            ? { type: "filter_text_response", content: "[\n  1\n]" }
            : { type: "filter_text_response", content: "", error: "Invalid filter: bad" },
        );
      } else if (payload.type === "show_toast_request") {
        resolve(payload.message);
      } else if (payload.type === "error_response") {
        reject(new Error(payload.error));
      }
    });
  });

  try {
    instance.postMessage({
      id: "boot",
      replyId: null,
      pluginRefId: "test",
      pluginName: "test",
      context,
      payload: { type: "boot_request", ...bootRequest },
    });
    expect(JSON.parse(await toast)).toEqual([
      { content: "[\n  1\n]" },
      { content: "", error: "Invalid filter: bad" },
    ]);
    expect(requests).toEqual([
      { type: "filter_text_request", language: "jsonpath", text: '{"a":1}', query: "$.a" },
      { type: "filter_text_request", language: "xpath", text: "<a/>", query: "//b[" },
    ]);
  } finally {
    await instance.terminate();
    await rm(dir, { recursive: true, force: true });
  }
});

import { URL } from "node:url";
import type { PluginDefinition } from "@yaakapp/api";
import type { CallHttpAuthenticationResponse } from "@yaakapp-internal/plugins";
import type { Request } from "aws4";
import aws4 from "aws4";

export const plugin: PluginDefinition = {
  authentication: {
    name: "awsv4",
    label: "AWS Signature",
    shortLabel: "AWS v4",
    args: [
      { name: "accessKeyId", label: "Access Key ID", type: "text", password: <REDACTED> },
      {
        name: "secretAccessKey",
        label: "Secret Access Key",
        type: "text",
        password: <REDACTED>
      },
      {
        name: "service",
        label: "Service Name",
        type: "text",
        defaultValue: "sts",
        placeholder: "sts",
        description: "The service that is receiving the request (sts, s3, sqs, ...)",
      },
      {
        name: "region",
        label: "Region",
        type: "text",
        placeholder: "us-east-1",
        description: "The region that is receiving the request (defaults to us-east-1)",
        optional: true,
      },
      {
        name: "sessionToken",
        label: "Session Token",
        type: "text",
        password: <REDACTED>
        optional: true,
        description: "Only required if you are using temporary credentials",
      },
    ],
    onApply(_ctx, { values, ...args }): CallHttpAuthenticationResponse {
      const accessKeyId = String(values.accessKeyId || "");
      const secretAccessKey = <REDACTED> || "");
      const sessionToken = <REDACTED> || "") || undefined;

      const url = new URL(args.url);

      const headers: NonNullable<Request["headers"]> = {};
      for (const headerName of ["content-type", "host", "x-amz-date", "x-amz-security-token"]) {
        const v = args.headers.find((h) => h.name.toLowerCase() === headerName);
        if (v != null) {
          headers[headerName] = v.value;
        }
      }

      const signature = aws4.sign(
        {
          host: url.host,
          method: args.method,
          path: url.pathname + (url.search || ""),
          service: String(values.service || "sts"),
          region: values.region ? String(values.region) : undefined,
          headers,
          body: args.body ?? undefined,
          doNotEncodePath: true,
        },
        {
          accessKeyId,
          secretAccessKey,
          sessionToken,
        },
      );

      if (signature.headers == null) {
        return {};
      }

      return {
        setHeaders: Object.entries(signature.headers)
          .filter(([name]) => name !== "content-type") // Don't add this because we already have it
          .map(([name, value]) => ({ name, value: String(value || "") })),
      };
    },
  },
};

//! The example workspace offered during onboarding.
//!
//! Authored as JSON with `{{PLACEHOLDER}}` ids so requests can reference each
//! other (the chaining example names another request by id). Every placeholder
//! gets a fresh id per creation, so the example can be created more than once.

use crate::error::Result;
use crate::models::{Environment, Folder, HttpRequest, UpsertModelInfo, Workspace};
use crate::query_manager::QueryManager;
use crate::util::{BatchUpsertResult, UpdateSource};

const EXAMPLE_JSON: &str = include_str!("example_workspace.json");

const WORKSPACE_IDS: &[&str] = &["WORKSPACE"];
const ENVIRONMENT_IDS: &[&str] = &["ENV_BASE", "ENV_USER_2"];
const FOLDER_IDS: &[&str] = &[
    "FOLDER_BASICS",
    "FOLDER_VARIABLES",
    "FOLDER_CHAINING",
    "FOLDER_AUTH",
];
const REQUEST_IDS: &[&str] = &[
    "RQ_LIST_POSTS",
    "RQ_GET_POST",
    "RQ_CREATE_POST",
    "RQ_CURRENT_USER",
    "RQ_LIST_USERS",
    "RQ_POSTS_BY_FIRST_USER",
    "RQ_TODOS",
    "RQ_LOG_IN",
    "RQ_ME",
];

pub fn create_example_workspace(
    query_manager: &QueryManager,
    source: &UpdateSource,
) -> Result<BatchUpsertResult> {
    let resources = example_resources()?;
    Ok(query_manager.with_tx(|tx| {
        tx.batch_upsert(
            resources.workspaces,
            resources.environments,
            resources.folders,
            resources.http_requests,
            resources.grpc_requests,
            resources.websocket_requests,
            source,
        )
    })?)
}

fn example_resources() -> Result<BatchUpsertResult> {
    let mut json = EXAMPLE_JSON.to_string();
    let placeholders = WORKSPACE_IDS
        .iter()
        .map(|p| (*p, Workspace::generate_id()))
        .chain(ENVIRONMENT_IDS.iter().map(|p| (*p, Environment::generate_id())))
        .chain(FOLDER_IDS.iter().map(|p| (*p, Folder::generate_id())))
        .chain(REQUEST_IDS.iter().map(|p| (*p, HttpRequest::generate_id())));
    for (placeholder, id) in placeholders {
        json = json.replace(&format!("{{{{{placeholder}}}}}"), &id);
    }
    debug_assert!(!json.contains("{{"), "example workspace has an unmapped placeholder");
    Ok(serde_json::from_str(&json)?)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::init_in_memory;

    #[test]
    fn every_placeholder_is_mapped() {
        let json = serde_json::to_string(&example_resources().unwrap()).unwrap();
        assert!(!json.contains("{{"), "unmapped placeholder in {json}");
    }

    #[test]
    fn chained_request_references_a_created_request() {
        let (query_manager, _blobs, _rx) = init_in_memory().unwrap();
        let created = create_example_workspace(&query_manager, &UpdateSource::Background).unwrap();
        assert_eq!(created.workspaces.len(), 1);
        let workspace_id = &created.workspaces[0].id;

        let db = query_manager.connect();
        let requests = db.list_http_requests(workspace_id).unwrap();
        assert_eq!(requests.len(), REQUEST_IDS.len());
        assert_eq!(db.list_folders(workspace_id).unwrap().len(), FOLDER_IDS.len());
        assert_eq!(db.list_environments(workspace_id).unwrap().len(), ENVIRONMENT_IDS.len());

        let list_users = requests.iter().find(|r| r.name == "List users").unwrap();
        let chained = requests.iter().find(|r| r.name == "Posts by the first user").unwrap();
        let param = &chained.url_parameters[0].value;
        assert!(param.contains(&format!("request='{}'", list_users.id)), "{param}");
    }

    #[test]
    fn creating_twice_makes_two_workspaces() {
        let (query_manager, _blobs, _rx) = init_in_memory().unwrap();
        create_example_workspace(&query_manager, &UpdateSource::Background).unwrap();
        create_example_workspace(&query_manager, &UpdateSource::Background).unwrap();
        assert_eq!(query_manager.connect().list_workspaces().unwrap().len(), 2);
    }
}

