import classNames from "classnames";
import { useAtomValue } from "jotai";
import { memo } from "react";
import { hoveredParentDepthFamily, isAncestorHoveredFamily } from "./atoms";

export const TreeIndentGuide = memo(function TreeIndentGuide({
  treeId,
  depth,
  ancestorIds,
}: {
  treeId: string;
  depth: number;
  ancestorIds: string[];
}) {
  const parentDepth = useAtomValue(hoveredParentDepthFamily(treeId));
  const isHovered = useAtomValue(isAncestorHoveredFamily({ treeId, ancestorIds }));

  return (
    <div className="flex">
      {Array.from({ length: depth }).map((_, i) => (
        <div
          // oxlint-disable-next-line react/no-array-index-key
          key={i}
          className={classNames(
            "w-[calc(1rem+0.5px)] border-r border-r-text-subtlest",
            !(parentDepth === i + 1 && isHovered) && "opacity-30",
          )}
        />
      ))}
    </div>
  );
});

import { useEffect, useState } from "react";

interface Props {
  /** A URL for the body the host already stored. */
  bodyUrl?: string;
  data?: Uint8Array;
  mimeType?: string;
}

export function AudioViewer({ bodyUrl, data, mimeType }: Props) {
  const [src, setSrc] = useState<string>();

  useEffect(() => {
    if (bodyUrl) {
      setSrc(bodyUrl);
    } else if (data) {
      // The type matters here in a way it doesn't for an image: a media element goes by what
      // the blob declares rather than sniffing it, so an Ogg labelled as MP3 won't play
      const blob = new Blob([new Uint8Array(data)], { type: mimeType ?? "audio/mpeg" });
      const objectUrl = URL.createObjectURL(blob);
      setSrc(objectUrl);
      return () => URL.revokeObjectURL(objectUrl);
    } else {
      setSrc(undefined);
    }
  }, [bodyUrl, data, mimeType]);

  // oxlint-disable-next-line jsx-a11y/media-has-caption
  return <audio className="w-full" controls src={src} />;
}

import classNames from "classnames";
import { useEffect, useState } from "react";

type Props = { className?: string; mimeType?: string } & (
  | {
      /** A URL for the body the host already stored. */
      bodyUrl: string;
    }
  | {
      data: ArrayBuffer;
    }
);

export function ImageViewer({ className, mimeType, ...props }: Props) {
  const [src, setSrc] = useState<string>();
  const bodyUrl = "bodyUrl" in props ? props.bodyUrl : null;
  const data = "data" in props ? props.data : null;

  useEffect(() => {
    if (bodyUrl != null) {
      setSrc(bodyUrl);
    } else if (data != null) {
      const blob = new Blob([data], { type: mimeType ?? "image/png" });
      const objectUrl = URL.createObjectURL(blob);
      setSrc(objectUrl);
      return () => URL.revokeObjectURL(objectUrl);
    } else {
      setSrc(undefined);
    }
  }, [bodyUrl, data, mimeType]);

  return (
    <img
      src={src}
      alt="Response preview"
      className={classNames(className, "max-w-full max-h-full")}
    />
  );
}

import { useEffect, useState } from "react";

interface Props {
  /** A URL for the body the host already stored. */
  bodyUrl?: string;
  data?: Uint8Array;
  mimeType?: string;
}

export function VideoViewer({ bodyUrl, data, mimeType }: Props) {
  const [src, setSrc] = useState<string>();

  useEffect(() => {
    if (bodyUrl) {
      setSrc(bodyUrl);
    } else if (data) {
      // As in AudioViewer: a media element trusts the declared type instead of sniffing
      const blob = new Blob([new Uint8Array(data)], { type: mimeType ?? "video/mp4" });
      const objectUrl = URL.createObjectURL(blob);
      setSrc(objectUrl);
      return () => URL.revokeObjectURL(objectUrl);
    } else {
      setSrc(undefined);
    }
  }, [bodyUrl, data, mimeType]);

  // oxlint-disable-next-line jsx-a11y/media-has-caption
  return <video className="w-full" controls src={src} />;
}
